import { MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, smoothstep, texture, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, BoxGeometry } = THREE;

  const root = new Group();
  root.name = 'features-card-2';

  const resources = [];
  const cleanupHandlers = [];
  let disposed = false;

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = {
    ink: visualSpec.colors?.ink ?? '#16161d',
    paper: visualSpec.colors?.paper ?? '#e8ecf2',
    accent: visualSpec.colors?.accent ?? '#ff2a38',
    surface: visualSpec.colors?.surface ?? '#0b0b10'
  };

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    color(colors.surface),
    color(colors.ink),
    smoothstep(0.0, 1.0, uv().y)
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const cardWidth = 3.2;
  const cardHeight = cardWidth * (320 / 512);

  const plateGeometry = new BoxGeometry(cardWidth, cardHeight, 0.08);
  const plateMaterial = new MeshBasicNodeMaterial({
    color: colors.surface
  });
  const plate = new Mesh(plateGeometry, plateMaterial);
  plate.name = 'machined-surface-plate';
  plate.position.set(0, 0, -0.08);
  root.add(plate);
  resources.push(plateGeometry, plateMaterial);

  const imageGeometry = new PlaneGeometry(cardWidth, cardHeight);
  const imageMaterial = new MeshBasicNodeMaterial({
    color: colors.paper,
    transparent: true,
    depthWrite: false
  });
  const imagePlane = new Mesh(imageGeometry, imageMaterial);
  imagePlane.name = 'floating-accent-sprite';
  imagePlane.position.set(0, 0, 0);
  root.add(imagePlane);
  resources.push(imageGeometry, imageMaterial);

  const accentGeometry = new BoxGeometry(cardWidth * 0.72, 0.025, 0.018);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: colors.accent
  });
  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.name = 'signal-red-foreground-accent';
  accent.position.set(0, -cardHeight * 0.58, 0.12);
  root.add(accent);
  resources.push(accentGeometry, accentMaterial);

  const cornerGeometry = new BoxGeometry(0.025, cardHeight * 0.34, 0.018);
  const cornerMaterial = new MeshBasicNodeMaterial({
    color: colors.accent
  });
  const corner = new Mesh(cornerGeometry, cornerMaterial);
  corner.name = 'signal-red-depth-marker';
  corner.position.set(cardWidth * 0.46, cardHeight * 0.35, 0.13);
  root.add(corner);
  resources.push(cornerGeometry, cornerMaterial);

  const textureUrl = config.imageUrl;
  let loadedTexture = null;

  if (textureUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(textureUrl).then((loaded) => {
      if (disposed) {
        loaded.dispose?.();
        return;
      }

      loadedTexture = loaded;
      loadedTexture.colorSpace = THREE.SRGBColorSpace;
      loadedTexture.needsUpdate = true;

      loadedTexture.offset.set(0, 0);
      loadedTexture.repeat.set(1, 1);

      imageMaterial.map = texture(loadedTexture);
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  imagePlane.onBeforeRender = (_renderer, _scene, camera) => {
    if (!disposed && camera) {
      imagePlane.quaternion.copy(camera.quaternion);
    }
  };

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const cleanup of cleanupHandlers) {
      try {
        cleanup();
      } catch {}
    }

    if (loadedTexture) {
      loadedTexture.dispose?.();
      loadedTexture = null;
    }

    for (const resource of resources) {
      resource.dispose?.();
    }

    root.traverse((object) => {
      object.onBeforeRender = null;
    });
  };

  return root;
}
